#!/bin/zsh
# Local development build of PushBar.app (this Mac's architecture only).
# No Xcode required — Command Line Tools are enough. To ship a release to
# everyone's in-app updater, use ./release.sh instead.
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
FEED="${UPDATE_FEED-https://raw.githubusercontent.com/jonpikereally/Push3InterfaceControl/main/updates/latest.json}"
cat > Sources/PushBar/Version.swift <<SWIFT
// Generated by build.sh / release.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
    static let updateFeed = "$FEED"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/pushbar-modcache"
mkdir -p "$CACHE" PushBar.app/Contents/MacOS
cp Resources/Info.plist PushBar.app/Contents/Info.plist
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" PushBar.app/Contents/Info.plist
swiftc -O -target arm64-apple-macos13 -module-cache-path "$CACHE" -o PushBar.app/Contents/MacOS/PushBar Sources/PushBar/*.swift
codesign --force --sign - PushBar.app
echo "Built PushBar.app v$VERSION ($BUILT)"
